ALTER POLICY clinical_reference_admin_insert ON public.clinical_reference_values WITH CHECK ((select public.current_user_has_role('admin'::public.app_role)));
ALTER POLICY clinical_reference_admin_update ON public.clinical_reference_values USING ((select public.current_user_has_role('admin'::public.app_role))) WITH CHECK ((select public.current_user_has_role('admin'::public.app_role)));
ALTER POLICY clinical_reference_read ON public.clinical_reference_values USING (is_active = true OR (select public.current_user_has_role('admin'::public.app_role)));
ALTER POLICY insurance_companies_admin_it_read ON public.insurance_companies USING ((select public.current_user_has_role('admin'::public.app_role)) OR (select public.current_user_has_role('it_admin'::public.app_role)));
ALTER POLICY insurance_service_tariffs_admin_delete ON public.insurance_service_tariffs USING ((select public.current_user_has_role('admin'::public.app_role)));
ALTER POLICY insurance_service_tariffs_admin_insert ON public.insurance_service_tariffs WITH CHECK ((select public.current_user_has_role('admin'::public.app_role)));
ALTER POLICY insurance_service_tariffs_admin_read ON public.insurance_service_tariffs USING ((select public.current_user_has_role('admin'::public.app_role)) OR (select public.current_user_has_role('accountant'::public.app_role)));
ALTER POLICY insurance_service_tariffs_admin_update ON public.insurance_service_tariffs USING ((select public.current_user_has_role('admin'::public.app_role))) WITH CHECK ((select public.current_user_has_role('admin'::public.app_role)));
ALTER POLICY canteen_operations_broadcast_read ON realtime.messages USING (realtime.topic() = 'canteen:operations' AND ((select public.current_user_has_role('admin'::public.app_role)) OR (select public.current_user_has_role('canteen'::public.app_role))));
ALTER POLICY "clinical staff read patient documents storage" ON storage.objects USING (bucket_id = 'patient-documents' AND ((select public.current_user_is_clinical_staff()) OR (select public.current_user_has_role('accountant'::public.app_role))));
ALTER POLICY "outside lab storage delete" ON storage.objects USING (bucket_id = 'outside-lab' AND ((select public.current_user_has_role('admin'::public.app_role)) OR (select public.current_user_has_role('practitioner'::public.app_role))));
ALTER POLICY "outside lab storage read" ON storage.objects USING (bucket_id = 'outside-lab' AND ((select public.current_user_has_role('admin'::public.app_role)) OR (select public.current_user_has_role('practitioner'::public.app_role)) OR (select public.current_user_has_role('nurse'::public.app_role)) OR (select public.current_user_has_role('midwife'::public.app_role)) OR (select public.current_user_has_role('specialist_nurse'::public.app_role)) OR (select public.current_user_has_role('lab_technician'::public.app_role))) AND split_part(name, '/', 1) IN (SELECT (patients.id)::text FROM public.patients));
ALTER POLICY "outside lab storage upload" ON storage.objects WITH CHECK (bucket_id = 'outside-lab' AND ((select public.current_user_has_role('admin'::public.app_role)) OR (select public.current_user_has_role('practitioner'::public.app_role)) OR (select public.current_user_has_role('nurse'::public.app_role)) OR (select public.current_user_has_role('midwife'::public.app_role)) OR (select public.current_user_has_role('specialist_nurse'::public.app_role)) OR (select public.current_user_has_role('lab_technician'::public.app_role))) AND split_part(name, '/', 1) IN (SELECT (patients.id)::text FROM public.patients));